static OPJ_BOOL opj_j2k_write_sot(opj_j2k_t * p_j2k, OPJ_BYTE * p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 * p_data_written, const opj_stream_private_t * p_stream, opj_event_mgr_t * p_manager) {
    OPJ_UINT32 written = 0;
    OPJ_UINT32 sot_length = 16; /* Standard SOT length: 2 (marker) + 2 (tile number) + 4 (total length) + 2 (current part) + 2 (number of parts) */
    OPJ_BYTE * buffer = p_data;

    if (p_total_data_size < sot_length) {
        return OPJ_FALSE;
    }

    /* Write SOT marker (0xFF91) */
    buffer[0] = 0xFF;
    buffer[1] = 0x91;

    /* Write tile number (2 bytes) */
    buffer[2] = (OPJ_BYTE)(p_j2k->current_tile_number >> 8);
    buffer[3] = (OPJ_BYTE)(p_j2k->current_tile_number & 0xFF);

    /* Write total length (4 bytes) */
    buffer[4] = (OPJ_BYTE)(p_j2k->sot_total_length >> 24);
    buffer[5] = (OPJ_BYTE)(p_j2k->sot_total_length >> 16);
    buffer[6] = (OPJ_BYTE)(p_j2k->sot_total_length >> 8);
    buffer[7] = (OPJ_BYTE)(p_j2k->sot_total_length & 0xFF);

    /* Write current part number and number of parts (2 bytes each) */
    buffer[8] = (OPJ_BYTE)(p_j2k->current_part_number >> 8);
    buffer[9] = (OPJ_BYTE)(p_j2k->current_part_number & 0xFF);
    buffer[10] = (OPJ_BYTE)(p_j2k->number_of_parts >> 8);
    buffer[11] = (OPJ_BYTE)(p_j2k->number_of_parts & 0xFF);

    /* Write remaining zeros (if needed for alignment) */
    for (written = 12; written < sot_length; ++written) {
        buffer[written] = 0;
    }

    *p_data_written = sot_length;
    return opj_stream_write_data(p_stream, buffer, sot_length, p_manager);
}

static OPJ_BOOL opj_j2k_get_sot_values(OPJ_BYTE * p_header_data, OPJ_UINT32 p_header_size, OPJ_UINT32 * p_tile_no, OPJ_UINT32 * p_tot_len, OPJ_UINT32 * p_current_part, OPJ_UINT32 * p_num_parts, opj_event_mgr_t * p_manager) {
    if (!p_header_data || p_header_size < 12) {
        return OPJ_FALSE;
    }

    /* Read tile number (2 bytes) */
    *p_tile_no = ((OPJ_UINT32)p_header_data[2] << 8) | p_header_data[3];

    /* Read total length (4 bytes) */
    *p_tot_len = ((OPJ_UINT32)p_header_data[4] << 24) |
                 ((OPJ_UINT32)p_header_data[5] << 16) |
                 ((OPJ_UINT32)p_header_data[6] << 8) |
                  (OPJ_UINT32)p_header_data[7];

    /* Read current part number and number of parts (2 bytes each) */
    *p_current_part = ((OPJ_UINT32)p_header_data[8] << 8) | p_header_data[9];
    *p_num_parts = ((OPJ_UINT32)p_header_data[10] << 8) | p_header_data[11];

    return OPJ_TRUE;
}

static OPJ_BOOL opj_j2k_write_sot(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size,
                                  OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream,
                                  opj_event_mgr_t *p_manager) {
    OPJ_UINT32 header_size = 13; // Standard size for SOT marker
    OPJ_UINT32 written = 0;
    OPJ_BYTE sot_marker[13] = { 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 };

    if (!p_data || p_total_data_size < header_size) {
        return OPJ_FALSE;
    }

    if (!opj_write_bytes(sot_marker, p_data, header_size, p_stream, p_manager)) {
        return OPJ_FALSE;
    }

    written = header_size;
    *p_data_written = written;
    return OPJ_TRUE;
}

static OPJ_BOOL opj_j2k_get_sot_values(OPJ_BYTE *p_header_data, OPJ_UINT32 p_header_size,
                                       OPJ_UINT32 *p_tile_no, OPJ_UINT32 *p_tot_len,
                                       OPJ_UINT32 *p_current_part, OPJ_UINT32 *p_num_parts,
                                       opj_event_mgr_t *p_manager) {
    if (!p_header_data || p_header_size < 13) {
        return OPJ_FALSE;
    }

    if (p_tile_no) {
        *p_tile_no = ((OPJ_UINT32)p_header_data[4]) << 8 | p_header_data[5];
    }

    if (p_tot_len) {
        *p_tot_len = ((OPJ_UINT32)p_header_data[6]) << 24 | ((OPJ_UINT32)p_header_data[7]) << 16 |
                     ((OPJ_UINT32)p_header_data[8]) << 8 | p_header_data[9];
    }

    if (p_current_part) {
        *p_current_part = p_header_data[10];
    }

    if (p_num_parts) {
        *p_num_parts = p_header_data[11];
    }

    return OPJ_TRUE;
}

static OPJ_BOOL opj_j2k_write_sot(opj_j2k_t *p_j2k, OPJ_BYTE *p_data, OPJ_UINT32 p_total_data_size, OPJ_UINT32 *p_data_written, const opj_stream_private_t *p_stream, opj_event_mgr_t *p_manager) {
    OPJ_UINT32 written = 0;
    OPJ_BYTE *buf = p_data;
    OPJ_UINT32 len = 0;
    OPJ_UINT32 tile_part = p_j2k->current_tile_part_number;
    OPJ_UINT32 num_parts = p_j2k->num_tile_parts;

    if (!buf || !p_data_written || !p_stream) {
        return OPJ_FALSE;
    }

    *p_data_written = 0;

    /* SOT marker (0xFF91) */
    if (written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    OPJ_WRITE_UINT16(buf + written, 0xFF91);
    written += 2;

    /* Length of SOT (initial placeholder; will be overwritten later) */
    if (written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    OPJ_WRITE_UINT16(buf + written, 0);
    written += 2;

    /* Tile number (starting from 1) */
    if (written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    OPJ_WRITE_UINT16(buf + written, tile_part + 1);
    written += 2;

    /* Part number and total parts */
    if (written + 2 > p_total_data_size) {
        return OPJ_FALSE;
    }
    OPJ_WRITE_UINT16(buf + written, (tile_part << 8) | num_parts);
    written += 2;

    /* Final update of the SOT length */
    OPJ_WRITE_UINT16(buf + 2, written - 4);

    if (opj_stream_write_data(p_stream, buf, written, p_manager) != written) {
        return OPJ_FALSE;
    }

    *p_data_written = written;
    return OPJ_TRUE;
}

static OPJ_BOOL opj_j2k_get_sot_values(OPJ_BYTE *p_header_data, OPJ_UINT32 p_header_size, OPJ_UINT32 *p_tile_no, OPJ_UINT32 *p_tot_len, OPJ_UINT32 *p_current_part, OPJ_UINT32 *p_num_parts, opj_event_mgr_t *p_manager) {
    if (!p_header_data || !p_tile_no || !p_tot_len || !p_current_part || !p_num_parts) {
        return OPJ_FALSE;
    }

    if (p_header_size < 8) {
        return OPJ_FALSE;
    }

    *p_tot_len = OPJ_READ_UINT16(p_header_data + 2);
    *p_tile_no = OPJ_READ_UINT16(p_header_data + 4);
    *p_current_part = (OPJ_UINT32)((OPJ_UINT16)(p_header_data[6] & 0xF0) >> 4);
    *p_num_parts = (OPJ_UINT32)(p_header_data[6] & 0x0F);

    return OPJ_TRUE;
}
